package com.family.littlelearning;
import org.json.*;
import java.util.*;

/** Rules for the eleven additional native games. No presentation or reward side effects. */
final class ExtraRules {
 static final int[] DIGITS={0x3F,0x06,0x5B,0x4F,0x66,0x6D,0x7D,0x07,0x7F,0x6F};
 static JSONObject put(JSONObject s,String key,Object v){try{return s.put(key,v);}catch(JSONException e){throw new IllegalArgumentException(e);}}
 static JSONArray arr(int... values){JSONArray a=new JSONArray();for(int n:values)a.put(n);return a;}
 static List<Integer> ints(JSONArray a){List<Integer> out=new ArrayList<>();if(a!=null)for(int i=0;i<a.length();i++)out.add(a.optInt(i));return out;}
 static JSONArray array(List<Integer> a){return new JSONArray(a);}
 static JSONObject task(String key,JSONObject s,Content c){try{return c.banks.getJSONArray(key).getJSONObject(s.getInt("index"));}catch(JSONException e){throw new IllegalArgumentException(e);}}
 static JSONArray groups(String key,Content c){for(int i=0;i<c.catalog.length();i++){JSONObject g=c.catalog.optJSONObject(i);if(key.equals(g.optString("key")))return g.optJSONArray("groups");}throw new IllegalArgumentException("Unknown game");}
 static JSONObject fresh(String key,int group,int index,Content c){JSONObject s=new JSONObject();put(s,"group",group);put(s,"index",index);put(s,"solved",false);put(s,"selected",-1);put(s,"answer",-1);put(s,"cursor",0);JSONObject q=task(key,s,c);
  switch(key){
   case "sharing":int[] counts=new int[q.optInt("bowls")];put(s,"values",arr(counts));put(s,"take",false);break;
   case "pinyin":case "characters":case "idioms":case "bakery":put(s,"chosen",new JSONArray());put(s,"follow",false);break;
   case "clock":put(s,"minutes",q.optInt("start"));put(s,"seconds",0);put(s,"hand",q.optString("mode").equals("seconds")?2:0);break;
   case "matches":put(s,"mask",q.optInt("initial"));break;
   case "sorting":put(s,"jars",cloneArray(q.optJSONArray("jars")));put(s,"history",new JSONArray());break;
   case "ruler":put(s,"origin",q.optString("mode").equals("offset")?4:0);put(s,"pair",new JSONArray());put(s,"found",new JSONArray());break;
   case "beads":int[] blank=new int[q.optJSONArray("blanks").length()];Arrays.fill(blank,-1);put(s,"values",arr(blank));put(s,"active",0);break;
   case "tangram":JSONArray ps=new JSONArray(),solution=q.optJSONArray("solution");for(int i=0;i<7;i++){JSONArray ref=solution.optJSONArray(i);ps.put(arr(-1,-1,index<16?ref.optInt(2):0,index<16?ref.optInt(3):0));}put(s,"placements",ps);put(s,"piece",0);put(s,"x",0);put(s,"y",0);put(s,"rotation",ps.optJSONArray(0).optInt(2));put(s,"flip",ps.optJSONArray(0).optInt(3));break;
   default:throw new IllegalArgumentException("Unsupported game "+key);
  }return s;
 }
 static JSONArray cloneArray(JSONArray a){try{return new JSONArray(a.toString());}catch(JSONException e){throw new IllegalArgumentException(e);}}
 static List<String> pool(JSONObject q){List<String> p=new ArrayList<>();JSONArray answer=q.optJSONArray("answer"),extras=q.optJSONArray("extras");for(int i=0;i<answer.length();i++)p.add(answer.optString(i));for(int i=0;i<extras.length();i++)p.add(extras.optString(i));return p;}
 static List<Integer> order(int size,int seed){List<Integer> a=new ArrayList<>();for(int i=0;i<size;i++)a.add(i);Collections.shuffle(a,new Random(seed*7919L+83));return a;}
 static boolean workshop(JSONObject q,JSONObject s){JSONArray answer=q.optJSONArray("answer"),chosen=s.optJSONArray("chosen");List<String> pool=pool(q);if(chosen==null||answer.length()!=chosen.length())return false;for(int i=0;i<answer.length();i++){int n=chosen.optInt(i,-1);if(n<0||n>=pool.size()||!pool.get(n).equals(answer.optString(i)))return false;}return true;}
 static int decodeDigit(int mask){for(int i=0;i<10;i++)if(DIGITS[i]==mask)return i;return -1;}
 static boolean matchTrue(int mask){if(mask>>>23!=0)return false;int a=decodeDigit(mask&127),b=decodeDigit(mask>>>7&127),c=decodeDigit(mask>>>14&127),op=mask>>>21&3;return a>=0&&b>=0&&c>=0&&(op==1||op==3)&&(op==3?a+b:a-b)==c;}
 static boolean matchAccepts(JSONObject q,int mask){int initial=q.optInt("initial");return Integer.bitCount(initial&~mask)==1&&Integer.bitCount(mask&~initial)==1&&matchTrue(mask);}
 static boolean sorted(JSONArray jars){for(int i=0;i<jars.length();i++){JSONArray j=jars.optJSONArray(i);if(j.length()==0)continue;if(j.length()!=4)return false;for(int k=1;k<4;k++)if(j.optInt(k)!=j.optInt(0))return false;}return true;}
 static String moveFruit(JSONObject s,int from,int to){JSONArray jars=s.optJSONArray("jars");if(from==to||from<0||to<0||from>=jars.length()||to>=jars.length())return "先选择有水果的罐子。";JSONArray a=jars.optJSONArray(from),b=jars.optJSONArray(to);if(a.length()==0||b.length()>=4||(b.length()>0&&b.optInt(b.length()-1)!=a.optInt(a.length()-1)))return "只能放进空罐，或相同水果的上面。";JSONArray history=s.optJSONArray("history");history.put(cloneArray(jars));if(history.length()>300)history.remove(0);b.put(a.optInt(a.length()-1));a.remove(a.length()-1);put(s,"selected",-1);return "";}
 static boolean satisfied(String key,JSONObject s,Content c){JSONObject q=task(key,s,c);switch(key){
  case "sharing":int total=0;JSONArray values=s.optJSONArray("values");if(values==null||values.length()!=q.optInt("bowls"))return false;for(int i=0;i<values.length();i++){int v=values.optInt(i);if(v!=q.optInt("total")/q.optInt("bowls"))return false;total+=v;}return q.optInt("total")-total==q.optInt("total")%q.optInt("bowls");
  case "pinyin":case "characters":case "idioms":case "bakery":return workshop(q,s)&&(q.optJSONArray("choices").length()==0||s.optInt("answer",-1)==q.optInt("correctChoice"));
  case "clock":String mode=q.optString("mode");return mode.equals("conversion")?s.optInt("answer",-1)==q.optInt("correctChoice"):s.optInt(mode.equals("seconds")?"seconds":"minutes")==q.optInt("target");
  case "matches":return matchAccepts(q,s.optInt("mask"));
  case "sorting":return sorted(s.optJSONArray("jars"));
  case "ruler":String m=q.optString("mode");List<Integer> marks=ints(q.optJSONArray("marks")),pair=ints(s.optJSONArray("pair"));int length=pair.size()==2?Math.abs(pair.get(0)-pair.get(1)):-1;boolean aligned=marks.contains(q.optInt("objectStart")-s.optInt("origin"))&&marks.contains(q.optInt("objectStart")-s.optInt("origin")+q.optInt("length"));switch(m){case "measure":return aligned&&q.optInt("objectStart")==s.optInt("origin")&&s.optInt("answer",-1)==q.optInt("length");case "offset":return aligned&&s.optInt("answer",-1)==q.optInt("length");case "missingNumber":return s.optInt("answer",-1)==q.optInt("blank");case "target":return length==q.optInt("length");case "explore":return new HashSet<>(ints(s.optJSONArray("found"))).equals(new HashSet<>(ints(q.optJSONArray("distances"))));}return false;
  case "beads":JSONArray blanks=q.optJSONArray("blanks"),chosen=s.optJSONArray("values"),options=q.optJSONArray("options"),seq=q.optJSONArray("sequence");for(int i=0;i<blanks.length();i++){int n=chosen.optInt(i,-1);if(n<0||n>=options.length()||!options.optJSONArray(n).toString().equals(seq.optJSONArray(blanks.optInt(i)).toString()))return false;}return true;
  case "tangram":Set<Integer> occupied=new HashSet<>();JSONArray placements=s.optJSONArray("placements");if(placements==null||placements.length()!=7)return false;for(int i=0;i<7;i++){int[] p=ints(placements.optJSONArray(i)).stream().mapToInt(Integer::intValue).toArray();if(p.length!=4||p[0]<0||p[1]<0||!inBounds(i,p))return false;for(int cell:coverage(i,p))if(!occupied.add(cell))return false;}return occupied.equals(new HashSet<>(ints(q.optJSONArray("target"))));
 }return false;}
 static final int[][][] SHAPES={{{0,0},{4,0},{2,2}},{{0,0},{4,0},{2,2}},{{0,0},{2,0},{0,2}},{{0,0},{2,0},{1,1}},{{0,0},{2,0},{1,1}},{{1,0},{2,1},{1,2},{0,1}},{{1,0},{1,2},{0,3},{0,1}}};
 static double[][] polygon(int piece,int[] p){double[][] out=new double[SHAPES[piece].length][2];double minX=100,minY=100;for(int i=0;i<out.length;i++){double x=SHAPES[piece][i][0]*(p[3]==1?-1:1),y=SHAPES[piece][i][1];for(int r=0;r<p[2];r++){double old=x;x=-y;y=old;}out[i][0]=x;out[i][1]=y;minX=Math.min(minX,x);minY=Math.min(minY,y);}for(double[] pt:out){pt[0]+=p[0]-minX;pt[1]+=p[1]-minY;}return out;}
 static boolean inBounds(int piece,int[] p){if(p[2]<0||p[2]>3||p[3]<0||p[3]>1)return false;for(double[] pt:polygon(piece,p))if(pt[0]<0||pt[1]<0||pt[0]>7||pt[1]>7)return false;return true;}
 static Set<Integer> coverage(int piece,int[] p){double[][] poly=polygon(piece,p);double[][] offsets={{.5,1./6},{5./6,.5},{.5,5./6},{1./6,.5}};Set<Integer> out=new HashSet<>();for(int y=0;y<7;y++)for(int x=0;x<7;x++)for(int k=0;k<4;k++){double px=x+offsets[k][0],py=y+offsets[k][1];boolean pos=true,neg=true;for(int i=0;i<poly.length;i++){double[] a=poly[i],b=poly[(i+1)%poly.length];double cross=(b[0]-a[0])*(py-a[1])-(b[1]-a[1])*(px-a[0]);pos&=cross>=-.00001;neg&=cross<=.00001;}if(pos||neg)out.add((y*7+x)*4+k);}return out;}
 static String place(JSONObject s){int piece=s.optInt("piece");int[] p={s.optInt("x"),s.optInt("y"),s.optInt("rotation"),s.optInt("flip")};if(!inBounds(piece,p))return "木片超出拼板，请移回来。";Set<Integer> own=coverage(piece,p);JSONArray placements=s.optJSONArray("placements");for(int i=0;i<7;i++){if(i==piece)continue;int[] other=ints(placements.optJSONArray(i)).stream().mapToInt(Integer::intValue).toArray();if(other[0]>=0&&!Collections.disjoint(own,coverage(i,other)))return "这里有另一块木片，换个位置。";}try{placements.put(piece,arr(p));}catch(JSONException e){throw new IllegalArgumentException(e);}return "已放好第 "+(piece+1)+" 块木片";}
 static void validate(String key,JSONObject s,Content c)throws Exception{
  if(c.banks==null||!c.banks.has(key))throw new IllegalArgumentException("Unknown saved game");int index=s.getInt("index"),group=s.getInt("group");JSONArray gs=groups(key,c);if(index<0||index>=c.banks.getJSONArray(key).length()||group<0||group>=gs.length()||!ints(gs.getJSONObject(group).getJSONArray("indices")).contains(index))throw new IllegalArgumentException("Invalid game index");JSONObject q=task(key,s,c);
  if(s.optInt("cursor")<0||s.optInt("cursor")>100||s.optInt("answer",-1)<-1)throw new IllegalArgumentException("Invalid selection");
  switch(key){case "sharing":List<Integer> counts=ints(s.getJSONArray("values"));if(counts.size()!=q.getInt("bowls")||counts.stream().anyMatch(n->n<0)||counts.stream().mapToInt(Integer::intValue).sum()>q.getInt("total"))throw new IllegalArgumentException("Invalid bowls");break;
  case "pinyin":case "characters":case "idioms":case "bakery":List<Integer> chosen=ints(s.getJSONArray("chosen"));if(new HashSet<>(chosen).size()!=chosen.size()||chosen.size()>q.getJSONArray("answer").length()||chosen.stream().anyMatch(n->n<0||n>=pool(q).size())||(s.optBoolean("follow")&&!workshop(q,s)))throw new IllegalArgumentException("Invalid word");break;
  case "clock":if(s.getInt("minutes")<0||s.getInt("minutes")>=720||s.getInt("seconds")<0||s.getInt("seconds")>=60||s.getInt("hand")<0||s.getInt("hand")>2)throw new IllegalArgumentException("Invalid clock");break;
  case "matches":int mask=s.getInt("mask"),initial=q.getInt("initial");if(mask<0||mask>>>23!=0||(mask!=initial&&(Integer.bitCount(mask&~initial)!=1||Integer.bitCount(initial&~mask)!=1)))throw new IllegalArgumentException("Invalid matches");break;
  case "sorting":JSONArray jars=s.getJSONArray("jars"),original=q.getJSONArray("jars");if(jars.length()!=original.length())throw new IllegalArgumentException("Invalid jars");Map<Integer,Integer> before=fruitCounts(original),after=fruitCounts(jars);if(!before.equals(after)||s.getJSONArray("history").length()>300)throw new IllegalArgumentException("Invalid fruits");for(int i=0;i<s.getJSONArray("history").length();i++)if(!fruitCounts(s.getJSONArray("history").getJSONArray(i)).equals(before))throw new IllegalArgumentException("Invalid undo");break;
  case "ruler":if(s.getInt("origin")<0||s.getInt("origin")>4||s.optInt("answer",-1)>8||!ints(q.getJSONArray("marks")).containsAll(ints(s.getJSONArray("pair")))||s.getJSONArray("pair").length()>2||!ints(q.getJSONArray("distances")).containsAll(ints(s.getJSONArray("found"))))throw new IllegalArgumentException("Invalid ruler");break;
  case "beads":JSONArray values=s.getJSONArray("values");if(values.length()!=q.getJSONArray("blanks").length()||s.getInt("active")<0||s.getInt("active")>=values.length())throw new IllegalArgumentException("Invalid beads");for(int n:ints(values))if(n< -1||n>=q.getJSONArray("options").length())throw new IllegalArgumentException("Invalid bead");break;
  case "tangram":JSONArray placements=s.getJSONArray("placements");if(placements.length()!=7||s.getInt("piece")<0||s.getInt("piece")>6)throw new IllegalArgumentException("Invalid tangram");Set<Integer> cells=new HashSet<>();for(int i=0;i<7;i++){int[] p=ints(placements.getJSONArray(i)).stream().mapToInt(Integer::intValue).toArray();if(p.length!=4||p[2]<0||p[2]>3||p[3]<0||p[3]>1)throw new IllegalArgumentException("Invalid piece");if(p[0]>=0){if(!inBounds(i,p))throw new IllegalArgumentException("Piece outside");for(int cell:coverage(i,p))if(!cells.add(cell))throw new IllegalArgumentException("Overlapping pieces");}}break;
  }if(s.optBoolean("solved")&&!satisfied(key,s,c))throw new IllegalArgumentException("Invalid solved state");
 }
 static Map<Integer,Integer> fruitCounts(JSONArray jars)throws JSONException{Map<Integer,Integer> out=new HashMap<>();for(int i=0;i<jars.length();i++){JSONArray jar=jars.getJSONArray(i);if(jar.length()>4)throw new IllegalArgumentException("Jar overflow");for(int n:ints(jar))out.put(n,out.getOrDefault(n,0)+1);}return out;}
}
